const{useState,useEffect,useRef}=React,INITIAL_WORLDS=[{id:1,title:"C\xE1mara de las pistas",category:"Comprensi\xF3n literal",textType:"Texto Narrativo",learningOutcome:"RA1: Localiza informaci\xF3n expl\xEDcita (objetos, materiales y condiciones) dentro de textos narrativos comprob\xE1ndola mediante citas textuales.",strategyTip:"Lee buscando datos exactos (n\xFAmeros, nombres, objetos) que est\xE1n escritos directamente en el texto.",status:"available",sceneEmoji:"\u{1F3DB}\uFE0F\u2728",thumbnail:"./assets/world-1.png",bgGradient:"from-amber-900 via-amber-700 to-yellow-600",artifact:{name:"Llave del Reloj Solar",icon:"\u{1F5DD}\uFE0F",desc:"Reliquia recuperada al localizar informaci\xF3n expl\xEDcita con precisi\xF3n."},explorationIntro:"En esta primera c\xE1mara aprender\xE1s a localizar datos exactos que est\xE1n escritos directamente en el pergamino sin inventar ni suponer detalles externos.",readingTitle:"El Secreto del Reloj de Arena de Marinilla",readingPassage:["En la galer\xEDa m\xE1s antigua del Archivo de los Mundos Perdidos, el b\xFAho guardi\xE1n Aurelio custodiaba el Reloj de Arena Solar. Cada viernes a las cinco de la tarde, cuando el sol te\xF1\xEDa de oro las monta\xF1as de Marinilla, Aurelio giraba el reloj exactamente tres veces hacia la izquierda usando su pluma plateada.",'Dentro del pedestal de piedra reposaba un cofre de madera de cedro cerrado con dos candados de bronce. Una inscripci\xF3n tallada en la base advert\xEDa a los aprendices: "Quien desee abrir el cofre para restaurar el primer fragmento deber\xE1 pronunciar el nombre del \xE1rbol sagrado y entregar cuatro semillas de roble dorado al guardi\xE1n del umbral".'],glossary:[{term:"Custodiaba",def:"Vigilaba y proteg\xEDa con mucho cuidado."},{term:"Pedestal",def:"Base s\xF3lida de piedra que sostiene una estatua o reliquia."},{term:"Umbral",def:"Entrada o puerta principal de un recinto sagrado."}],clueHighlight:'F\xEDjate en los datos exactos del primer y segundo p\xE1rrafo: el instrumento que usa Aurelio ("pluma plateada"), el material del cofre ("madera de cedro") y la cantidad de semillas ("cuatro semillas de roble dorado").',missions:[{id:"m1_1",stepTitle:"Misi\xF3n 1 de 3: Localizaci\xF3n de objetos y acciones",question:"Seg\xFAn lo escrito expl\xEDcitamente en el primer p\xE1rrafo, \xBFcon qu\xE9 objeto giraba Aurelio el Reloj de Arena Solar cada viernes?",options:["Con una llave de bronce antiguo.","Con su pluma plateada.","Con una rama de roble dorado."],correctOption:1,evidencePrompt:"Justifica tu decisi\xF3n seleccionando el fragmento exacto del texto que demuestra tu respuesta:",evidences:['"...Aurelio giraba el reloj exactamente tres veces hacia la izquierda usando su pluma plateada."','"...en la galer\xEDa m\xE1s antigua del Archivo de los Mundos Perdidos..."','"...cerrado con dos candados de bronce."'],correctEvidence:0,scaffoldHint:'Busca al final del primer p\xE1rrafo la palabra "usando". Ah\xED encontrar\xE1s el instrumento exacto y la cita que lo respalda.',feedbackSuccess:"\xA1Excelente localizaci\xF3n literal! Identificaste el dato expl\xEDcito y lo respaldaste con la cita textual exacta."},{id:"m1_2",stepTitle:"Misi\xF3n 2 de 3: Identificaci\xF3n de caracter\xEDsticas expl\xEDcitas",question:"De acuerdo con el texto, \xBFde qu\xE9 material estaba construido el cofre que reposaba dentro del pedestal de piedra?",options:["De piedra tallada y cristal azul.","De oro macizo de las monta\xF1as.","De madera de cedro con dos candados de bronce."],correctOption:2,evidencePrompt:"\xBFQu\xE9 evidencia textual respalda tu respuesta?",evidences:['"Cada viernes a las cinco de la tarde, cuando el sol te\xF1\xEDa de oro las monta\xF1as..."','"Dentro del pedestal de piedra reposaba un cofre de madera de cedro cerrado con dos candados de bronce."','"...pronunciar el nombre del \xE1rbol sagrado..."'],correctEvidence:1,scaffoldHint:"Observa la primera oraci\xF3n del segundo p\xE1rrafo: all\xED se describe el cofre que est\xE1 dentro del pedestal.",feedbackSuccess:"\xA1Muy bien, Guardi\xE1n! Has distinguido con exactitud los materiales descritos en la lectura."},{id:"m1_3",stepTitle:"Misi\xF3n 3 de 3: Condici\xF3n literal del pergamino",question:"\xBFQu\xE9 elementos exactos exige la inscripci\xF3n tallada para poder abrir el cofre y restaurar el primer fragmento?",options:["Pronunciar el nombre del \xE1rbol sagrado y entregar cuatro semillas de roble dorado.","Girar el reloj cinco veces a la medianoche en silencio.","Entregar dos plumas plateadas y tres monedas de bronce."],correctOption:0,evidencePrompt:"Selecciona la cita del texto que comprueba tu elecci\xF3n:",evidences:['"...el b\xFAho guardi\xE1n Aurelio custodiaba el Reloj de Arena Solar."','"...giraba el reloj exactamente tres veces hacia la izquierda..."','"...deber\xE1 pronunciar el nombre del \xE1rbol sagrado y entregar cuatro semillas de roble dorado al guardi\xE1n del umbral."'],correctEvidence:2,scaffoldHint:'Lee las palabras que est\xE1n entre comillas ("...") al final del segundo p\xE1rrafo.',feedbackSuccess:"\xA1C\xE1mara de las Pistas superada! Has recuperado la primera historia y desbloqueado el Bosque de las Inferencias."}]},{id:2,title:"Bosque de las inferencias",category:"Comprensi\xF3n inferencial",textType:"Texto Narrativo - Descriptivo",learningOutcome:"RA2: Deduce informaci\xF3n impl\xEDcita (condiciones clim\xE1ticas, tiempo transcurrido y motivaciones) relacionando indicios del texto.",strategyTip:"Une las pistas del texto con lo que ya sabes del mundo para descubrir lo que el autor sugiere sin decirlo directamente.",status:"locked",sceneEmoji:"\u{1F333}\u{1F52E}",thumbnail:"./assets/world-2.png",bgGradient:"from-teal-900 via-emerald-800 to-cyan-700",artifact:{name:"Cristal de la Deducci\xF3n",icon:"\u{1F52E}",desc:"Otorgado por deducir informaci\xF3n impl\xEDcita a partir de las pistas del texto."},explorationIntro:"En este bosque la respuesta no est\xE1 dicha directamente con las mismas palabras; deber\xE1s unir las pistas del texto para deducir lo que ocurre.",readingTitle:"Los Viajeros del Sendero de Niebla",readingPassage:["Cuando Valeria y Tom\xE1s cruzaron el puente hacia el Bosque de los Susurros, el cielo se cubri\xF3 de nubes color ceniza. Tom\xE1s guard\xF3 su mapa de papel dentro de su chaqueta impermeable, subi\xF3 el cierre hasta el cuello y observ\xF3 c\xF3mo su aliento se convert\xEDa en peque\xF1as nubes blancas al hablar.","A pocos metros, encontraron una fogata cuyas brasas a\xFAn brillaban con un suave color naranja y, junto a un tronco ca\xEDdo, vieron una taza met\xE1lica que todav\xEDa desprend\xEDa vapor de chocolate caliente. Sin embargo, alrededor del campamento no se escuchaba ninguna voz y las huellas sobre el barro fresco se dirig\xEDan apresuradamente hacia la cueva del norte."],glossary:[{term:"Impermeable",def:"Prenda que no deja pasar el agua ni la lluvia."},{term:"Brasas",def:"Trozos de le\xF1a ardiente que conservan el calor del fuego."},{term:"Apresuradamente",def:"Con mucha prisa o rapidez."}],clueHighlight:"Observa las pistas f\xEDsicas: el aliento blanco y el cierre hasta el cuello indican fr\xEDo; el vapor del chocolate y las brasas encendidas indican que alguien estuvo all\xED hace muy pocos minutos.",missions:[{id:"m2_1",stepTitle:"Misi\xF3n 1 de 3: Inferencia clim\xE1tica y ambiental",question:"Aunque el texto no menciona la temperatura con un n\xFAmero, \xBFqu\xE9 se puede inferir sobre el clima en el Bosque de los Susurros?",options:["Hac\xEDa mucho calor porque hab\xEDa una fogata encendida.","Hac\xEDa mucho fr\xEDo y estaba pr\xF3ximo a llover.","Era un d\xEDa soleado y seco de verano."],correctOption:1,evidencePrompt:"\xBFQu\xE9 pistas del texto te permiten hacer esta inferencia?",evidences:['"...el cielo se cubri\xF3 de nubes color ceniza... subi\xF3 el cierre hasta el cuello y observ\xF3 c\xF3mo su aliento se convert\xEDa en peque\xF1as nubes blancas..."','"...Valeria y Tom\xE1s cruzaron el puente hacia el Bosque de los Susurros..."','"...las huellas sobre el barro fresco se dirig\xEDan hacia la cueva del norte."'],correctEvidence:0,scaffoldHint:"Piensa: \xBFen qu\xE9 tipo de clima nuestro aliento sale como humo blanco y nos subimos la chaqueta hasta el cuello?",feedbackSuccess:"\xA1Inferencia impecable! Relacionaste las nubes ceniza, el abrigo y el vapor del aliento para deducir el fr\xEDo."},{id:"m2_2",stepTitle:"Misi\xF3n 2 de 3: Deducci\xF3n temporal de los hechos",question:"\xBFQu\xE9 podemos deducir sobre las personas que estaban en el campamento antes de que llegaran Valeria y Tom\xE1s?",options:["Que abandonaron el campamento hace muchos meses.","Que se hab\xEDan marchado hac\xEDa muy pocos minutos de forma r\xE1pida.","Que nunca hubo nadie acampando en ese lugar."],correctOption:1,evidencePrompt:"Elige la evidencia del texto que sostiene esta conclusi\xF3n l\xF3gica:",evidences:['"Tom\xE1s guard\xF3 su mapa de papel dentro de su chaqueta impermeable..."','"...las brasas a\xFAn brillaban con un suave color naranja y... una taza met\xE1lica que todav\xEDa desprend\xEDa vapor... las huellas sobre el barro fresco se dirig\xEDan apresuradamente..."','"Cuando Valeria y Tom\xE1s cruzaron el puente hacia el Bosque..."'],correctEvidence:1,scaffoldHint:"Si una taza de chocolate a\xFAn echa vapor en medio del fr\xEDo, \xBFhace cu\xE1nto tiempo la sirvieron?",feedbackSuccess:"\xA1Gran trabajo deductivo! Si las brasas brillan y la bebida a\xFAn humea, significa que se fueron hace instantes."},{id:"m2_3",stepTitle:"Misi\xF3n 3 de 3: Prop\xF3sito impl\xEDcito de una acci\xF3n",question:"\xBFPor qu\xE9 raz\xF3n Tom\xE1s guard\xF3 el mapa de papel dentro de su chaqueta impermeable al mirar el cielo?",options:["Para evitar que el mapa se mojara y se da\xF1ara si empezaba a llover.","Porque ya no necesitaba el mapa para regresar a su casa.","Para esconderlo de su compa\xF1era Valeria."],correctOption:0,evidencePrompt:"Selecciona la pista textual que explica el motivo de Tom\xE1s:",evidences:['"...junto a un tronco ca\xEDdo, vieron una taza met\xE1lica..."','"...el cielo se cubri\xF3 de nubes color ceniza. Tom\xE1s guard\xF3 su mapa de papel dentro de su chaqueta impermeable..."','"...alrededor del campamento no se escuchaba ninguna voz..."'],correctEvidence:1,scaffoldHint:'Relaciona las "nubes color ceniza" (lluvia inminente) con el material del mapa ("papel") y la chaqueta ("impermeable").',feedbackSuccess:"\xA1Bosque de las Inferencias completado! Ahora tienes acceso a la Ciudad de las Voces."}]},{id:3,title:"Ciudad de las voces",category:"Intenci\xF3n y significado",textType:"Texto Instructivo y Normativo",learningOutcome:"RA3: Reconoce el prop\xF3sito comunicativo de textos instructivos e interpreta expresiones en lenguaje figurado seg\xFAn su contexto.",strategyTip:"Preg\xFAntate: \xBFPara qu\xE9 escribi\xF3 el autor este texto? \xBFQu\xE9 quiere lograr en el lector?",status:"locked",sceneEmoji:"\u{1F3F0}\u{1F319}",thumbnail:"./assets/world-3.png",bgGradient:"from-indigo-950 via-purple-900 to-slate-800",artifact:{name:"Pluma de los Escribas",icon:"\u{1FAB6}",desc:"S\xEDmbolo de quien comprende el prop\xF3sito comunicativo y el sentido de las instrucciones."},explorationIntro:"En la Ciudad de las Voces analizar\xE1s textos instructivos e informativos para descubrir qu\xE9 pretende lograr el autor y qu\xE9 significan sus expresiones en contexto.",readingTitle:"Manual del Restaurador de Pergaminos Antiguos",readingPassage:["AVISO OFICIAL DEL ARCHIVO CENTRAL: Todo guardi\xE1n que ingrese al Taller de Restauraci\xF3n debe seguir estrictamente estos pasos antes de tocar un libro milenario: 1) Lavar y secar completamente sus manos; 2) Colocarse los guantes de algod\xF3n blanco; 3) Usar la brocha de cerdas suaves para retirar el polvo superficial desde el centro hacia los bordes, nunca en sentido contrario.",'Recuerda que las p\xE1ginas antiguas son "alas de mariposa": cualquier presi\xF3n brusca o rastro de humedad puede quebrar sus fibras para siempre y borrar la memoria de un pueblo entero.'],glossary:[{term:"Milenario",def:"Que tiene mil a\xF1os o much\xEDsima antig\xFCedad."},{term:"Superficial",def:"Que est\xE1 solamente en la capa de encima."},{term:"Fibras",def:"Hilos fin\xEDsimos que forman el papel antiguo."}],clueHighlight:'Presta atenci\xF3n a la finalidad de las reglas enumeradas (1, 2, 3) y a la met\xE1fora "alas de mariposa" explicada en el segundo p\xE1rrafo.',missions:[{id:"m3_1",stepTitle:"Misi\xF3n 1 de 3: Intenci\xF3n comunicativa del texto",question:"\xBFCu\xE1l es el prop\xF3sito principal por el cual fue escrito este texto del Archivo Central?",options:["Entretener al lector con una leyenda fant\xE1stica sobre mariposas m\xE1gicas.","Instruir y orientar paso a paso sobre c\xF3mo manipular los libros antiguos sin da\xF1arlos.","Vender guantes de algod\xF3n y brochas de cerdas suaves a los visitantes."],correctOption:1,evidencePrompt:"\xBFQu\xE9 parte del texto demuestra que su intenci\xF3n es dar instrucciones de cuidado?",evidences:['"Todo guardi\xE1n que ingrese al Taller de Restauraci\xF3n debe seguir estrictamente estos pasos antes de tocar un libro milenario: 1) Lavar... 2) Colocarse... 3) Usar..."','"...borrar la memoria de un pueblo entero."','"...desde el centro hacia los bordes..."'],correctEvidence:0,scaffoldHint:"F\xEDjate en c\xF3mo el texto ordena acciones numeradas (1, 2, 3) que el lector debe cumplir.",feedbackSuccess:"\xA1Correcto! Reconociste la estructura y prop\xF3sito de un texto instructivo."},{id:"m3_2",stepTitle:"Misi\xF3n 2 de 3: Interpretaci\xF3n de lenguaje figurado",question:'Cuando el manual afirma que las p\xE1ginas antiguas son "alas de mariposa", \xBFqu\xE9 significa esa expresi\xF3n dentro del texto?',options:["Que los libros pueden salir volando por las ventanas del taller.","Que las p\xE1ginas est\xE1n decoradas con dibujos de insectos de colores.","Que las hojas son sumamente fr\xE1giles y delicadas ante cualquier descuido."],correctOption:2,evidencePrompt:"\xBFQu\xE9 explicaci\xF3n del propio texto confirma ese significado?",evidences:['"...cualquier presi\xF3n brusca o rastro de humedad puede quebrar sus fibras para siempre..."','"...Colocarse los guantes de algod\xF3n blanco..."','"AVISO OFICIAL DEL ARCHIVO CENTRAL..."'],correctEvidence:0,scaffoldHint:'Lee lo que est\xE1 inmediatamente despu\xE9s de los dos puntos (:) tras "alas de mariposa".',feedbackSuccess:"\xA1Muy bien interpretado! Comprendiste el sentido figurado apoy\xE1ndote en el contexto de la frase."},{id:"m3_3",stepTitle:"Misi\xF3n 3 de 3: Secuencia y procedimiento",question:"Seg\xFAn las instrucciones del manual, \xBFc\xF3mo debe utilizarse la brocha de cerdas suaves sobre el libro?",options:["Frotando con fuerza desde los bordes hacia el centro con las manos h\xFAmedas.","Retirando el polvo superficial desde el centro hacia los bordes, nunca al rev\xE9s.","Antes de lavarse las manos y sin ponerse los guantes de algod\xF3n."],correctOption:1,evidencePrompt:"Selecciona el fragmento exacto que valida tu decisi\xF3n:",evidences:['"1) Lavar y secar completamente sus manos;"','"3) Usar la brocha de cerdas suaves para retirar el polvo superficial desde el centro hacia los bordes, nunca en sentido contrario."','"...borrar la memoria de un pueblo entero."'],correctEvidence:1,scaffoldHint:"Revisa el paso n\xFAmero 3) en el primer p\xE1rrafo del manual.",feedbackSuccess:"\xA1Ciudad de las Voces liberada! El Tribunal de los Lectores ha abierto sus puertas."}]},{id:4,title:"Tribunal de los lectores",category:"Comprensi\xF3n cr\xEDtica",textType:"Texto Argumentativo - Cr\xF3nico",learningOutcome:"RA4: Eval\xFAa la solidez de diferentes posturas y argumentos en un texto, distinguiendo opiniones sin sustento de argumentos con pruebas.",strategyTip:"Compara qui\xE9n ofrece hechos y pruebas verificables frente a qui\xE9n solo expresa una opini\xF3n exagerada.",status:"locked",sceneEmoji:"\u2696\uFE0F\u{1F56F}\uFE0F",thumbnail:"./assets/world-4.png",bgGradient:"from-amber-950 via-stone-800 to-yellow-900",artifact:{name:"Balanza del Juicio Lector",icon:"\u2696\uFE0F",desc:"Concedida por contrastar posturas y evaluar argumentos con evidencias s\xF3lidas."},explorationIntro:"En el Tribunal evaluar\xE1s dos posturas distintas frente a un problema de la comunidad y tomar\xE1s una posici\xF3n cr\xEDtica justificada con hechos del texto.",readingTitle:"El Debate por la Biblioteca del Valle",readingPassage:['En el consejo del Valle de San Jos\xE9 se discute el futuro de la Biblioteca Escolar. El consejero Dar\xEDo propone cerrarla definitivamente y vender los libros impresos, asegurando que "hoy ning\xFAn estudiante necesita leer textos largos porque en las redes sociales hay videos de quince segundos sobre cualquier tema".','Por el contrario, la maestra Elena sostiene que la biblioteca debe fortalecerse con talleres y tabletas digitales de consulta, pues "los videos cortos informan r\xE1pido, pero la lectura profunda de libros e historias entrena la mente para investigar, dudar de las noticias falsas y argumentar con pruebas reales". Un estudio realizado en la escuela demostr\xF3 que los estudiantes que asisten al club de lectura resolvieron un 75% m\xE1s de retos de ciencias y convivencia.'],glossary:[{term:"Postura",def:"Posici\xF3n o punto de vista que alguien defiende frente a un tema."},{term:"Noticias falsas",def:"Informaci\xF3n enga\xF1osa que circula sin pruebas reales."},{term:"Argumentar",def:"Dar razones y pruebas claras para defender una idea."}],clueHighlight:"Compara qu\xE9 pruebas ofrece Dar\xEDo (una opini\xF3n general sin datos) frente a los datos verificables (75% m\xE1s de retos resueltos) y razones pedag\xF3gicas de la maestra Elena.",missions:[{id:"m4_1",stepTitle:"Misi\xF3n 1 de 3: Evaluaci\xF3n de argumentos y evidencias",question:"Desde una lectura cr\xEDtica, \xBFcu\xE1l de las dos posturas est\xE1 mejor fundamentada con hechos comprobables dentro del texto?",options:["La del consejero Dar\xEDo, porque los videos de quince segundos reemplazan toda la ciencia.","La de la maestra Elena, porque explica el valor formativo de leer e incluye un dato del estudio escolar (75% de mejora).","Ninguna de las dos posturas presenta razones sobre la biblioteca."],correctOption:1,evidencePrompt:"\xBFQu\xE9 evidencia objetiva del texto respalda la solidez del argumento de Elena?",evidences:['"...vender los libros impresos, asegurando que hoy ning\xFAn estudiante necesita leer..."','"Un estudio realizado en la escuela demostr\xF3 que los estudiantes que asisten al club de lectura resolvieron un 75% m\xE1s de retos de ciencias y convivencia."','"En el consejo del Valle de San Jos\xE9 se discute el futuro de la Biblioteca..."'],correctEvidence:1,scaffoldHint:"Busca al final del segundo p\xE1rrafo el dato estad\xEDstico del estudio realizado en la escuela.",feedbackSuccess:"\xA1Excelente juicio cr\xEDtico! Distinguiste entre una afirmaci\xF3n sin pruebas y un argumento respaldado por evidencias."},{id:"m4_2",stepTitle:"Misi\xF3n 2 de 3: Detecci\xF3n de generalizaciones d\xE9biles",question:"\xBFCu\xE1l es el error principal en el argumento del consejero Dar\xEDo cuando pide cerrar la biblioteca?",options:["Que propone combinar libros impresos con tabletas digitales.","Que asume sin pruebas que ver videos de 15 segundos desarrolla las mismas habilidades que la lectura profunda.","Que quiere abrir m\xE1s clubes de lectura en la escuela."],correctOption:1,evidencePrompt:"Selecciona el fragmento donde se evidencia la postura reduccionista de Dar\xEDo:",evidences:['"...asegurando que hoy ning\xFAn estudiante necesita leer textos largos porque en las redes sociales hay videos de quince segundos sobre cualquier tema."','"...entrena la mente para investigar, dudar de las noticias falsas..."','"...fortalecerse con talleres y tabletas digitales de consulta..."'],correctEvidence:0,scaffoldHint:'Observa las palabras exactas de Dar\xEDo en el primer p\xE1rrafo cuando usa la palabra "ning\xFAn".',feedbackSuccess:"\xA1Muy bien! Identificaste una generalizaci\xF3n apresurada dentro del debate."},{id:"m4_3",stepTitle:"Misi\xF3n 3 de 3: Toma de postura fundamentada",question:"Seg\xFAn la propuesta de la maestra Elena, \xBFpor qu\xE9 la lectura profunda sigue siendo indispensable frente a las noticias de internet?",options:["Porque impide que los estudiantes utilicen computadores o tel\xE9fonos.","Porque entrena la mente para investigar, dudar de las noticias falsas y argumentar con pruebas reales.","Porque es la \xFAnica forma de pasar el tiempo libre en el recreo."],correctOption:1,evidencePrompt:"Elige la cita textual que sustenta esta conclusi\xF3n cr\xEDtica:",evidences:['"...la lectura profunda de libros e historias entrena la mente para investigar, dudar de las noticias falsas y argumentar con pruebas reales."','"El consejero Dar\xEDo propone cerrarla definitivamente..."','"...videos de quince segundos sobre cualquier tema."'],correctEvidence:0,scaffoldHint:"Revisa en el segundo p\xE1rrafo qu\xE9 beneficios menciona Elena sobre la lectura profunda.",feedbackSuccess:"\xA1Tribunal de los Lectores superado! Has desbloqueado la misi\xF3n final integradora: \xA1La B\xF3veda del Archivo!"}]},{id:5,title:"La b\xF3veda del archivo",category:"Misi\xF3n final",textType:"Misi\xF3n Integradora (Literal, Inferencial y Cr\xEDtica)",learningOutcome:"RA Integrador: Integra estrategias de comprensi\xF3n literal, inferencial y cr\xEDtica para resolver problemas complejos justificando cada decisi\xF3n con evidencia textual.",strategyTip:"Aplica los tres poderes adquiridos: localiza el dato exacto, conecta las pistas y valora el mensaje profundo del texto.",status:"locked",isFinalVault:!0,sceneEmoji:"\u{1F31F}\u{1F6AA}",thumbnail:"./assets/world-5.png",bgGradient:"from-amber-500 via-yellow-600 to-amber-800",artifact:{name:"C\xF3dice Maestro de los Mundos Perdidos",icon:"\u{1F451}",desc:"M\xE1xima distinci\xF3n otorgada al Guardi\xE1n que integra comprensi\xF3n literal, inferencial y cr\xEDtica con evidencia textual."},explorationIntro:"\xA1Has llegado a la B\xF3veda del Archivo! En esta misi\xF3n integradora demostrar\xE1s tu dominio completo: localizar\xE1s un dato expl\xEDcito, realizar\xE1s una inferencia y justificar\xE1s una decisi\xF3n cr\xEDtica con evidencias del texto.",readingTitle:"El C\xF3dice de las Tres Llaves de San Jos\xE9",readingPassage:['Frente a la gran puerta dorada de la B\xF3veda, el b\xFAho Aurelio extendi\xF3 el \xFAltimo pergamino integrador: "Hace cien a\xF1os, los fundadores ocultaron aqu\xED el C\xF3dice de la Memoria para protegerlo del Olvido Gris. El mecanismo de apertura consta de tres engranajes: el engranaje de Cobre se activa al mediod\xEDa; el de Plata responde \xFAnicamente cuando dos guardianes leen en voz alta al mismo tiempo; y el de Oro solo gira cuando se coloca sobre el altar una semilla de ceiba recolectada en la ribera del r\xEDo Negro".','Cuando el aprendiz Mateo intent\xF3 abrir la b\xF3veda \xE9l solo a las doce del d\xEDa llevando la semilla de ceiba en su bolsillo, el engranaje de Cobre brill\xF3 y el de Oro comenz\xF3 a girar, pero la puerta permaneci\xF3 inm\xF3vil y el engranaje de Plata sigui\xF3 apagado. En un mural cercano se le\xEDa: "Un verdadero Guardi\xE1n no busca el conocimiento para encerrarlo en soledad, sino para compartirlo con su comunidad".'],glossary:[{term:"C\xF3dice",def:"Libro antiguo manuscrito de gran valor hist\xF3rico y cultural."},{term:"Engranajes",def:"Piezas dentadas que se conectan entre s\xED para hacer funcionar un mecanismo."},{term:"Ribera",def:"Orilla de un r\xEDo o laguna."}],clueHighlight:"Esta misi\xF3n final eval\xFAa las 3 competencias: 1) Literal (qu\xE9 pide cada engranaje), 2) Inferencial (por qu\xE9 fall\xF3 Mateo al ir solo) y 3) Cr\xEDtica (el valor comunitario de la lectura).",missions:[{id:"m5_1",stepTitle:"Reto Integrador 1/3 (Nivel Literal): Informaci\xF3n expl\xEDcita",question:"Seg\xFAn el pergamino, \xBFqu\xE9 elemento espec\xEDfico se debe colocar sobre el altar para que gire el engranaje de Oro?",options:["Una semilla de ceiba recolectada en la ribera del r\xEDo Negro.","Una moneda de plata encontrada en la monta\xF1a.","Un reloj de cobre activado a la medianoche."],correctOption:0,evidencePrompt:"Selecciona la evidencia textual expl\xEDcita:",evidences:['"...el engranaje de Cobre se activa al mediod\xEDa..."','"...y el de Oro solo gira cuando se coloca sobre el altar una semilla de ceiba recolectada en la ribera del r\xEDo Negro."','"...el engranaje de Plata sigui\xF3 apagado."'],correctEvidence:1,scaffoldHint:'Localiza al final del primer p\xE1rrafo la condici\xF3n literal del "engranaje de Oro".',feedbackSuccess:"\xA1Paso 1 completado! Has localizado con precisi\xF3n la condici\xF3n literal del engranaje de Oro."},{id:"m5_2",stepTitle:"Reto Integrador 2/3 (Nivel Inferencial): Deducci\xF3n de causa",question:"\xBFPor qu\xE9 raz\xF3n no se abri\xF3 la puerta de la B\xF3veda cuando Mateo intent\xF3 activarla al mediod\xEDa con la semilla de ceiba?",options:["Porque lleg\xF3 de noche y olvid\xF3 llevar la semilla de ceiba.","Porque fue \xE9l solo, y el engranaje de Plata exig\xEDa que dos guardianes leyeran en voz alta al mismo tiempo.","Porque el engranaje de Cobre estaba roto desde hac\xEDa cien a\xF1os."],correctOption:1,evidencePrompt:"\xBFQu\xE9 fragmentos del texto permiten inferir la causa del fallo de Mateo?",evidences:['"...el de Plata responde \xFAnicamente cuando dos guardianes leen en voz alta al mismo tiempo... Cuando el aprendiz Mateo intent\xF3 abrir la b\xF3veda \xE9l solo... el engranaje de Plata sigui\xF3 apagado."','"Hace cien a\xF1os, los fundadores ocultaron aqu\xED el C\xF3dice de la Memoria..."','"...el engranaje de Cobre brill\xF3 y el de Oro comenz\xF3 a girar..."'],correctEvidence:0,scaffoldHint:'Une la condici\xF3n del engranaje de Plata ("dos guardianes") con lo que hizo Mateo ("intent\xF3 abrir la b\xF3veda \xE9l solo").',feedbackSuccess:"\xA1Inferencia maestra! Conectaste la regla del engranaje de Plata con el hecho de que Mateo acudi\xF3 solo."},{id:"m5_3",stepTitle:"Reto Integrador 3/3 (Nivel Cr\xEDtico): Justificaci\xF3n de sentido y valor",question:"Relacionando el funcionamiento del engranaje de Plata con el mensaje del mural, \xBFqu\xE9 ense\xF1anza cr\xEDtica transmiten los fundadores sobre la lectura y el conocimiento?",options:["Que el conocimiento debe guardarse en secreto para que nadie m\xE1s lo lea.","Que el aprendizaje y la lectura alcanzan su verdadero valor cuando se construyen y comparten en comunidad.","Que solo los metales preciosos tienen valor dentro de una biblioteca."],correctOption:1,evidencePrompt:"Justifica tu conclusi\xF3n seleccionando la evidencia del mural que respalda este prop\xF3sito:",evidences:['"...intent\xF3 abrir la b\xF3veda \xE9l solo a las doce del d\xEDa..."','"Un verdadero Guardi\xE1n no busca el conocimiento para encerrarlo en soledad, sino para compartirlo con su comunidad."','"...recolectada en la ribera del r\xEDo Negro."'],correctEvidence:1,scaffoldHint:"Lee la frase inscrita en el mural al final del segundo p\xE1rrafo.",feedbackSuccess:"\xA1FELICITACIONES, MAESTRO DEL ARCHIVO! Has completado las 15 misiones de los 5 mundos utilizando evidencias textuales."}]}],TeamCreditBadge=({onOpenPedagogicalSheet:o})=>React.createElement("div",{className:"flex items-center justify-between bg-[#161134]/95 border border-[#56478E] rounded-full px-3 py-1 my-1.5 shadow-sm"},React.createElement("div",{className:"flex items-center gap-1.5 text-[11px]"},React.createElement("span",{className:"text-[#F8C146]"},"\u2728"),React.createElement("span",{className:"text-gray-300"},"Idea y Dise\xF1o:"),React.createElement("strong",{className:"text-[#2CE5D8] font-extrabold tracking-wide"},"Eduqu\xE9monos con Tics")),o&&React.createElement("button",{onClick:o,className:"bg-[#281F54] hover:bg-[#372B70] text-[#F8C146] text-[10px] font-black px-2 py-0.5 rounded-full border border-[#F8C146]/40 transition-all"},"\u{1F4CB} Gu\xEDa Docente")),Magi